import { LMRouter, Message } from "@lm15/lm15";

const router = new LMRouter();
const request = {
  model: "bedrock-chat:deepseek.v3.2",
  system:
      "You are the field assistant for a wildlife research station. " +
      "Answer in two sentences.",
